import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useLanguage } from '../../context/LanguageContext';
import LanguageSelector from '../UI/LanguageSelector';

const Navbar = () => {
  const { t } = useLanguage();
  const location = useLocation();
  const [isFlashcardsOpen, setIsFlashcardsOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);

  const isActive = (path) => location.pathname === path;

  const flashcardItems = [
    { path: '/my_decks', icon: 'fas fa-layer-group', key: 'navMyDecks' },
    { path: '/new_deck', icon: 'fas fa-plus-circle', key: 'navNewDeck' },
    { path: '/add_cards', icon: 'fas fa-plus', key: 'navAddCards' },
    { path: '/study', icon: 'fas fa-graduation-cap', key: 'navStudy' },
    { path: '/import', icon: 'fas fa-file-import', key: 'navImport' }
  ];

  return (
    <nav className="navbar">
      <div className="logo">
        <i className="fas fa-language"></i>
        <span className="logo-text">Lingua Nova</span>
      </div>

      <div className={`nav-links ${isMobileMenuOpen ? 'mobile-open' : ''}`} id="nav-links">
        <Link 
          to="/" 
          className={isActive('/') ? 'active' : ''}
          onClick={() => setIsMobileMenuOpen(false)}
        >
          {t('navHome', 'Home')}
        </Link>

        <Link 
          to="/dialogues" 
          className={isActive('/dialogues') ? 'active' : ''}
          onClick={() => setIsMobileMenuOpen(false)}
        >
          {t('navDialogues', 'Diálogos')}
        </Link>

        <Link 
          to="/stories" 
          className={isActive('/stories') ? 'active' : ''}
          onClick={() => setIsMobileMenuOpen(false)}
        >
          {t('navStories', 'Histórias')}
        </Link>

        {/* Dropdown para Flashcards */}
        <div className="dropdown" id="flashcards-dropdown">
          <div 
            className="dropdown-toggle"
            onClick={() => setIsFlashcardsOpen(!isFlashcardsOpen)}
          >
            <span>{t('navFlashcards', 'Flashcards')}</span>
            <i className={`fas fa-chevron-down dropdown-icon ${isFlashcardsOpen ? 'open' : ''}`}></i>
          </div>
          <div className={`dropdown-menu ${isFlashcardsOpen ? 'show' : ''}`}>
            {flashcardItems.map((item) => (
              <Link 
                key={item.path}
                to={item.path} 
                className={`dropdown-item ${isActive(item.path) ? 'active' : ''}`}
                onClick={() => {
                  setIsFlashcardsOpen(false);
                  setIsMobileMenuOpen(false);
                }}
              >
                <i className={item.icon}></i>
                <span>{t(item.key, item.key)}</span>
              </Link>
            ))}
          </div>
        </div>

        <Link 
          to="/community" 
          className={isActive('/community') ? 'active' : ''}
          onClick={() => setIsMobileMenuOpen(false)}
        >
          {t('navCommunity', 'Comunidade')}
        </Link>
      </div>

      <div className="nav-actions">
        {/* Seletor de idioma de aprendizado */}
        <div className="language-icon-selector">
          <div className="icon-tooltip">
            <i className="fas fa-graduation-cap"></i>
            <span className="tooltip-text">{t('learningLabel', 'Aprendendo')}</span>
          </div>
          <LanguageSelector type="learning" />
        </div>

        {/* Seletor de idioma nativo */}
        <div className="language-icon-selector">
          <div className="icon-tooltip">
            <i className="fas fa-globe"></i>
            <span className="tooltip-text">{t('userLanguageLabel', 'Meu idioma')}</span>
          </div>
          <LanguageSelector type="native" />
        </div>

        {/* Menu do usuário */}
        <div className="user-menu">
          <div 
            className="user-avatar"
            onClick={() => setIsUserMenuOpen(!isUserMenuOpen)}
          ></div>
          <div className={`user-dropdown-menu ${isUserMenuOpen ? 'show' : ''}`}>
            <div className="user-dropdown-item" onClick={() => console.log('View Profile')}>
              <i className="fas fa-user"></i>
              <span>{t('userProfile', 'Meu Perfil')}</span>
            </div>
            <div className="user-dropdown-item" onClick={() => console.log('Settings')}>
              <i className="fas fa-cog"></i>
              <span>{t('userSettings', 'Configurações')}</span>
            </div>
            <div className="user-dropdown-divider"></div>
            <div className="user-dropdown-item logout-item" onClick={() => console.log('Logout')}>
              <i className="fas fa-sign-out-alt"></i>
              <span>{t('logoutButton', 'Sair')}</span>
            </div>
          </div>
        </div>
      </div>

      <div 
        className="mobile-menu-toggle" 
        id="mobile-menu-toggle"
        onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
      >
        <span></span>
        <span></span>
        <span></span>
      </div>
    </nav>
  );
};

export default Navbar;
